set-variable.value:
#[output application/java --- {
                            requestId: vars.raCurrentItem.id,
                            requestName: vars.raCurrentItem.name,
                            status: 'failed',
                            durationMs: 0,
                            error: error.description,
                            checksPassed: 0, checksFailed: 0, checksTotal: 0,
                            fullResult: {}
                        }]

ee:message.ee:set-payload:
%dw 2.0
output application/xlsx header=true
var report = vars.excelReport
var results = report.results default []
var total = report.totalRequests default 0
var passedCount = report.passedRequests default 0
var failedCount = report.failedRequests default 0
var duration = report.durationMs default 0

// Cell values are capped well under Excel's real 32,767-char-per-cell limit.
fun truncate(s) = if (s == null) '' else (if (sizeOf(s) > 30000) (substring(s, 0, 30000) ++ '…(truncated)') else s)
// sentBody/response.body are already serialized JSON text coming out of the app — pass those
// straight through; only actually re-encode real objects (headers, the Call Request log maps).
fun toJsonStr(v) = if (v == null) '' else (if (v is String) v else write(v, 'application/json'))

var summaryRows = [
    { Metric: 'Total Requests', Value: total },
    { Metric: 'Passed', Value: passedCount },
    { Metric: 'Failed', Value: failedCount },
    { Metric: 'Pass Rate', Value: if (total > 0) ((passedCount * 100.0 / total) as String {format: '0.0'}) ++ '%' else '0.0%' },
    { Metric: 'Total Duration (ms)', Value: duration },
]

var detailedBase = results map ((entry) -> {
    Request: entry.requestName default '',
    Status: if (entry.status == 'success') 'Pass' else 'Fail',
    'Duration (ms)': entry.durationMs default 0,
    'Checks Passed': entry.checksPassed default 0,
    'Checks Failed': entry.checksFailed default 0,
    'Checks Total': entry.checksTotal default 0,
    Error: entry.error default '',
})
var detailedRows =
    if (isEmpty(detailedBase)) [{ '#': '', Request: '(no main requests in this report)', Status: '', 'Duration (ms)': '', 'Checks Passed': '', 'Checks Failed': '', 'Checks Total': '', Error: '' }]
    else (detailedBase map ((row, i) -> { '#': i + 1 } ++ row))

// Request/Response Detail — the actual sent body/headers and received status/headers/body for
// the MAIN http call of every request (one row per iteration for an iterating request).
fun reqRespEntriesOf(entry) =
    if (entry.fullResult.iterating == true)
        (entry.fullResult.iterations default []) map ((it, idx) -> { name: entry.requestName default '', iterLabel: 'Iteration ' ++ ((idx + 1) as String), rr: it })
    else
        [{ name: entry.requestName default '', iterLabel: '', rr: entry.fullResult }]
var reqRespBase = (flatten(results map ((entry) -> reqRespEntriesOf(entry)))) map ((x) -> {
    Request: x.name,
    Iteration: x.iterLabel,
    'Sent Body': truncate(toJsonStr(x.rr.sentBody)),
    'Sent Headers': truncate(toJsonStr(x.rr.sentHeaders)),
    'Response Status': (x.rr.response.status default '') as String,
    'Response Headers': truncate(toJsonStr(x.rr.response.headers)),
    'Response Body': truncate(toJsonStr(x.rr.response.body)),
})
var reqRespRows =
    if (isEmpty(reqRespBase)) [{ '#': '', Request: '(no main requests in this report)', Iteration: '', 'Sent Body': '', 'Sent Headers': '', 'Response Status': '', 'Response Headers': '', 'Response Body': '' }]
    else (reqRespBase map ((row, i) -> { '#': i + 1 } ++ row))

// Pre/Post Steps Detail — every Call Request/Set Variable step that ran, pre-request or
// post-response, with what it sent/received (Call Request) or what it set (Set Variable).
fun callRequestResultText(step) =
    if (step.status == 'error') ('ERROR: ' ++ (step.error default 'unknown error'))
    else truncate(toJsonStr({ subStatus: step.subStatus, responseStatus: step.subResponseStatus, responseBody: step.subResponseBody, error: step.subError }))
fun stepRowsOf(name, iterLabel, pre, post) =
    ((pre default []) map ((step) -> {
        Request: name, Iteration: iterLabel, Phase: 'Pre-Request', 'Step Type': 'Call Request',
        'Input (target / value)': truncate(toJsonStr({ targetRequestId: step.requestId, body: step.inputBody, headers: step.inputHeaders })),
        Result: callRequestResultText(step),
    }))
    ++
    ((post default []) map ((step) ->
        if (step.'type' == 'setVariable')
            { Request: name, Iteration: iterLabel, Phase: 'Post-Response', 'Step Type': 'Set Variable',
              'Input (target / value)': step.name default '', Result: truncate(toJsonStr(step.value)) }
        else
            { Request: name, Iteration: iterLabel, Phase: 'Post-Response', 'Step Type': 'Call Request',
              'Input (target / value)': truncate(toJsonStr({ targetRequestId: step.requestId, body: step.inputBody, headers: step.inputHeaders })),
              Result: callRequestResultText(step) }
    ))
fun stepsOf(entry) = do {
    var fr = entry.fullResult
    var name = entry.requestName default ''
    ---
    if (fr.iterating == true)
        flatten((fr.iterations default []) map ((it, idx) -> stepRowsOf(name, 'Iteration ' ++ ((idx + 1) as String), it.preRequestLog, it.postResponseLog)))
    else
        stepRowsOf(name, '', fr.preRequestLog, fr.postResponseLog)
}
var stepsBase = flatten(results map ((entry) -> stepsOf(entry)))
var stepsRows =
    if (isEmpty(stepsBase)) [{ '#': '', Request: '', Iteration: '', Phase: '', 'Step Type': '', 'Input (target / value)': '(no pre-request or post-response steps ran across any request in this report)', Result: '' }]
    else (stepsBase map ((row, i) -> { '#': i + 1 } ++ row))

// Checks Detail — one row per check plus one row per condition right under it (every condition
// shown, not just the failing ones, mirroring ResponseViewer.jsx's CheckEntry) — condition rows
// leave Request/Iteration/Check blank and lead with a couple of spaces, since this writer has no
// outline/grouping support to show the nesting visually the way the POI version's collapsible
// groups did.
fun checkRowsOf(name, iterLabel, checks) =
    flatten((checks default []) map ((chk) -> do {
        var conds = chk.conditions default []
        var headerRow = { Check: chk.name default '', Condition: '', Result: if (chk.passed) 'Pass' else 'Fail', Detail: if (isEmpty(conds)) (chk.message default '') else '' }
        var condRows = conds map ((cond) -> {
            Check: '', Condition: '  ' ++ ((cond.left default '') ++ ' ' ++ (cond.operator default '') ++ ' ' ++ (cond.right default '')),
            Result: if (cond.passed) 'Pass' else 'Fail', Detail: cond.message default '',
        })
        ---
        [{ Request: name, Iteration: iterLabel } ++ headerRow] ++ (condRows map ((cr) -> { Request: '', Iteration: '' } ++ cr))
    }))
fun checksOf(entry) = do {
    var fr = entry.fullResult
    var name = entry.requestName default ''
    ---
    if (fr.iterating == true)
        flatten((fr.iterations default []) map ((it, idx) -> checkRowsOf(name, 'Iteration ' ++ ((idx + 1) as String), it.checks)))
    else
        checkRowsOf(name, '', fr.checks)
}
var checksBase = flatten(results map ((entry) -> checksOf(entry)))
var checksRows =
    if (isEmpty(checksBase)) [{ '#': '', Request: '', Iteration: '', Check: '', Condition: '', Result: '', Detail: '' }]
    else (checksBase map ((row, i) -> { '#': i + 1 } ++ row))
---
{
    Summary: summaryRows,
    'Detailed Results': detailedRows,
    'Request-Response Detail': reqRespRows,
    'Pre-Post Steps Detail': stepsRows,
    'Checks Detail': checksRows,
}
